import json,html,pathlib
p=pathlib.Path(__file__).parent
assets=json.loads((p/'assets.json').read_text()); A={x['title']:x for x in assets if 'local'in x}
def img(t,alt):
 a=A.get(t)
 return f'<a class="visual" href="{a["page"]}" target="_blank" rel="noopener"><img src="{a["local"]}" alt="{alt}" loading="lazy"></a>' if a else ''
def section(id,title,body,image=None):return f'<section id="{id}"><div class="section-head"><span>{id.upper()}</span><h2>{title}</h2></div>{img(*image) if image else ""}{body}</section>'
parts=[]
parts.append(section('influencies','Un art de síntesi', '''<h3>Influències artístiques</h3><p>L’arquitectura islàmica integra tradicions de les civilitzacions precedents. De l’art romà incorpora les columnes, l’arc de mig punt i les dovelles bicolors; de l’art bizantí, les voltes i les cúpules; del Pròxim Orient, els arcs apuntats i lobulats. En l’àmbit hispànic també incorpora la tradició de l’arc de ferradura visigòtic.</p><h3>Religió i ornamentació</h3><p>L’arquitectura ocupa un lloc central. La pintura, el mosaic i l’escultura s’apliquen especialment a la decoració. En els espais religiosos predominen els motius abstractes; en contextos civils també existeixen representacions figuratives.</p><div class="terms"><article><h4>Llaceria</h4><p>Trames de línies i figures geomètriques entrellaçades.</p></article><article><h4>Atauric</h4><p>Decoració vegetal de fulles i tiges estilitzades.</p></article><article><h4>Arabesc</h4><p>Composicions que entrellacen motius vegetals i geomètrics.</p></article><article><h4>Cal·ligrafia</h4><p>Inscripcions ornamentals, sovint amb textos religiosos.</p></article></div><p>Els mocàrabs són elements prismàtics que formen composicions semblants a estalactites en voltes i cúpules. La ceràmica decorada i vidriada completa molts revestiments.</p>''',('Dome of the Rock','Cúpula de la Roca a Jerusalem: planta central i gran cúpula')))
parts.append(section('evolucio','L’evolució d’al-Àndalus','''<div class="timeline"><article><b>Segles VIII–IX · Època omeia</b><p>Assimilació de tradicions anteriors i desenvolupament de l’arquitectura andalusina.</p></article><article><b>Segle X · Califat de Còrdova</b><p>Complexitat tècnica i riquesa ornamental: arcuacions, voltes de nervis i ampliacions de la mesquita de Còrdova.</p></article><article><b>Segle XI · Regnes de taifes</b><p>Desenvolupament de l’arquitectura palatina i d’arcs mixtilinis i polilobulats, com a l’Aljaferia.</p></article><article><b>Segles XII–XIII · Almohades</b><p>Arquitectura de composició austera que potencia l’estructura sense abandonar la decoració. La Giralda n’és un exemple.</p></article><article><b>Segles XIII–XV · Nassarites</b><p>Gran riquesa decorativa interior, amb guix, fusta, ceràmica, jardins i aigua. El conjunt de l’Alhambra n’és el gran referent.</p></article></div><h3>Situar el territori</h3><p>Al-Àndalus canvià d’extensió al llarg dels segles. Cal relacionar cada mapa amb el període representat, sense interpretar-lo com una frontera permanent.</p>''',('Al-Andalus','Mapa d’al-Àndalus l’any 732')))
parts.append(section('arquitectura','Com es construeix?', '''<ul><li>Predomini de volums geomètrics i composicions regulars, amb variacions segons el lloc i l’època.</li><li>Ús de maó i fusta, però també de pedra i altres materials segons el context.</li><li>Cobertes amb voltes i cúpules: nervades, gallonades i amb mocàrabs.</li><li>Columnes i pilars, sovint esvelts, per sostenir cobertes relativament lleugeres.</li><li>Arcs de ferradura, de mig punt, apuntats, lobulats, polilobulats i mixtilinis.</li><li>Contrast freqüent entre la sobrietat exterior i la riquesa ornamental interior: guix, ceràmica, marbre i fusta.</li></ul><div class="prompt"><b>Observa la imatge.</b> Localitza les columnes, la superposició d’arcs i les dovelles de dos colors. Quina funció estructural i visual tenen?</div>''',('Mosque–Cathedral of Córdoba','Interior de la mesquita de Còrdova amb columnes i arcs superposats')))
parts.append(section('mesquita','La mesquita: espai de pregària', '''<p>La mesquita respon a la necessitat de pregària col·lectiva. La forma hipòstila més habitual combina una sala coberta i un pati; també hi ha altres tipologies, incloses les de planta central.</p><div class="terms"><article><h4>Haram</h4><p>Sala d’oració, sovint dividida en naus.</p></article><article><h4>Alquibla</h4><p>Mur orientat cap a la Meca, amb excepcions històriques com Còrdova.</p></article><article><h4>Mihrab</h4><p>Fornícula que assenyala la direcció de la pregària.</p></article><article><h4>Minbar</h4><p>Trona des d’on es pronuncia el sermó.</p></article><article><h4>Maqsura</h4><p>Espai reservat al sobirà en algunes mesquites.</p></article><article><h4>Sahn</h4><p>Pati descobert, sovint porticat.</p></article><article><h4>Minaret</h4><p>Torre des d’on es crida a l’oració.</p></article><article><h4>Ablucions</h4><p>Rentat ritual abans de la pregària; requereix un punt d’aigua.</p></article></div><p>Exemples destacats: Damasc, Kairouan i Còrdova. La Cúpula de la Roca és un santuari de planta central amb una funció diferent de la mesquita congregacional.</p>''',('Great Mosque of Kairouan','Gran mesquita de Kairouan: pati, pòrtics i minaret')))
parts.append(section('civil','Palaus, fortaleses i banys', '''<h3>Arquitectura defensiva</h3><p>L’alcassaba és un recinte fortificat amb funcions militars i administratives. Els castells i les fortaleses aprofiten les irregularitats del terreny. Muralles, torres, merlets i portes monumentals protegeixen ciutats i conjunts palatins. Un exemple és el castell de la Suda de Tortosa.</p><h3>Arquitectura palatina</h3><p>Els palaus són residències de sobirans i prínceps. Poden formar autèntiques ciutats palatines, com Madīnat al-Zahrā’. Diferencien espais públics i privats, amb dependències distribuïdes al voltant de patis. Jardins i aigua articulen l’espai i relacionen art i natura.</p><p>Exemples: l’Aljaferia de Saragossa, l’Alhambra de Granada i el Generalife.</p><h3>Banys públics</h3><p>Els hammams tenen una funció higiènica, social i ritual. Hereus de la tradició termal, solen incloure vestíbul i sales freda, tèbia i calenta. Es localitzen sovint prop de mercats i mesquites.</p>''',('Generalife','Jardins i pati del Generalife, amb vegetació i aigua')))
parts.append(section('mudejar','L’art mudèjar: tradicions compartides', '''<p>El terme mudèjar deriva de l’àrab mudayyan, «aquell a qui s’ha permès quedar-se». Designa, en història de l’art, obres dels regnes cristians que incorporen formes, tècniques i materials de tradició hispanomusulmana.</p><p>En un mateix edifici conviuen elements romànics o gòtics —com els arcs de mig punt i apuntats— amb arcs de ferradura, lobulats i decoracions de tradició islàmica.</p><p>El maó és habitual en murs i pilars; el guix i la fusta destaquen en l’ornamentació. Les cobertes de fusta poden presentar teginats i estructures de tradició andalusina.</p><p>El període estudiat s’estén dels segles XI al XVI. Distingim una fase romanicomudèjar (segles XI–XII) i una fase goticomudèjar (segles XIII–XVI), amb diferències regionals.</p>''',('Santa María la Blanca','Interior de Santa María la Blanca de Toledo, amb arcs de ferradura')))
parts.append(section('focus','Quatre focus, moltes solucions', '''<div class="table-wrap"><table><thead><tr><th>Focus</th><th>Trets principals</th><th>Exemples</th></tr></thead><tbody><tr><td>Castellanolleonès</td><td>Romànic del maó; absis semicirculars, arcs de mig punt, cobertes de fusta i arcuacions cegues.</td><td>San Tirso i San Lorenzo de Sahagún; La Lugareja d’Arévalo.</td></tr><tr><td>Toledà</td><td>Tradició islàmica combinada amb formes cristianes. Arcs de ferradura, torres semblants a minarets i sinagogues amb rica decoració.</td><td>San Román, Santiago del Arrabal, Santo Tomé, Santa María la Blanca, sinagoga del Trànsit i Puerta del Sol.</td></tr><tr><td>Aragonès</td><td>Rica decoració exterior de maó, arcs cecs, motius geomètrics i ceràmica vidriada policroma.</td><td>Torres de San Salvador i San Martín de Terol; Magdalena i San Pablo de Saragossa.</td></tr><tr><td>Andalús</td><td>Estructures gòtiques combinades amb ornamentació de tradició nassarita, guixeries, mocàrabs i fusta.</td><td>Reales Alcázares de Sevilla, Capilla Real de Còrdova, Santa Marina i San Marcos de Sevilla; claustre de Guadalupe.</td></tr></tbody></table></div><h3>Toledo: arquitectura cristiana i jueva</h3><p>Santa María la Blanca distribueix l’espai en cinc naus amb pilars octagonals i arcs de ferradura. La sinagoga del Trànsit, del segle XIV, destaca per la seua ornamentació interior. La Puerta del Sol és una entrada mudèjar del recinte emmurallat.</p><h3>Aragó: el protagonisme del mur</h3><p>Les torres de planta quadrada incorporen arcuacions cegues, franges geomètriques i xarxes de rombes o panys de sebka. El maó i la ceràmica converteixen la superfície exterior en un element ornamental.</p><h3>Andalusia: espais palatins</h3><p>Al palau de Pere I dels Reales Alcázares destaquen el Saló dels Ambaixadors i les cobertes ornamentals. El claustre de Guadalupe, a Càceres, s’inclou en aquest àmbit d’influència i presenta un templet central.</p>''',('Torre de San Martín','Torre mudèjar de San Martín de Terol')))
parts.append(section('activitats','Mira, relaciona i explica', '''<ol class="activities"><li>Relaciona cada tradició artística amb un element incorporat a l’arquitectura islàmica.</li><li>Explica la diferència entre arc de ferradura, arc lobulat i arc apuntat.</li><li>Descriu el recorregut d’una persona des del pati fins a la sala d’oració i defineix cinc termes.</li><li>Compara la funció de l’aigua en una mesquita i en un palau.</li><li>Tria dos focus mudèjars i compara’n materials, decoració i edificis.</li><li>Redacta un comentari d’una imatge: identificació, context, funció, materials, estructura i ornamentació.</li></ol><details><summary>Orientacions per a l’autocorrecció</summary><p>1. Romà: columnes i mig punt; bizantí: voltes i cúpules; Pròxim Orient: arcs apuntats i lobulats; visigòtic: ferradura en el context hispànic.</p><p>2. Ferradura: prolonga la curvatura per davall del semicercle; lobulat: divideix l’intradós en lòbuls; apuntat: dos segments que convergeixen en un vèrtex.</p><p>3. Sahn, ablucions, haram, alquibla i mihrab. Afig minaret, minbar i maqsura si escau.</p><p>4. Purificació ritual a la mesquita; composició espacial, frescor i dimensió simbòlica i sensorial al palau.</p><p>5–6. Justifica cada tret amb elements visibles i evita identificar un estil només per un arc.</p></details>'''))
credits='<ul>'+''.join(f'<li><a href="{a["commons"]}">{html.escape(a["title"])}</a> · {html.escape(a.get("credit",{}).get("Artist",""))} · <a href="{a.get("credit",{}).get("LicenseUrl",a["commons"])}">{html.escape(a.get("credit",{}).get("LicenseShortName","Fitxa de llicència"))}</a></li>'for a in A.values())+'</ul>'
parts[1] += '<div class="map-extra"><h3>El territori almohade</h3><p>El mapa situa l’imperi almohade al Magrib i a la península Ibèrica; compara’l amb el mapa d’al-Àndalus de l’any 732.</p>'+img('Almohad Caliphate','Mapa de l’extensió de l’imperi almohade')+'</div>'

page='''<!doctype html><html lang="ca-valencia"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Art islàmic i mudèjar · Aula d’Història de l’Art</title><link rel="stylesheet" href="style.css"><body><a class="skip" href="#contingut">Salta al contingut</a><header><span>HISTÒRIA DE L’ART · BATXILLERAT</span><h1>Art islàmic<br>i art mudèjar</h1><p>Arquitectura, espai i ornamentació: un recorregut per les formes i els territoris.</p><a class="button" href="#influencies">Comença el recorregut ↓</a><button onclick="window.print()">Imprimeix / PDF</button></header><nav aria-label="Índex del recurs">'''+''.join(f'<a href="#{i}">{t}</a>'for i,t in [('influencies','Influències'),('evolucio','Evolució'),('arquitectura','Construcció'),('mesquita','Mesquita'),('civil','Art civil'),('mudejar','Mudèjar'),('focus','Focus'),('activitats','Activitats')])+'''</nav><main id="contingut"><aside class="intro"><b>Objectius d’aprenentatge</b><p>Reconèixer formes i materials, interpretar la funció dels espais, situar les etapes i comparar els focus mudèjars.</p></aside>'''+''.join(parts)+'''<section id="fonts"><h2>Fonts i crèdits</h2><p>Adaptació didàctica de les pàgines aportades (apartats 5.3–5.6), sense els peus d’imatge originals. S’han matisat algunes generalitzacions i corregit la datació de la sinagoga del Trànsit al segle XIV.</p><p>Les fotografies i els mapes procedeixen de les pàgines de Wikipèdia enllaçades. Cada imatge obri el seu article; la fitxa del fitxer a Wikimedia Commons identifica autoria i llicència. Les còpies locals eviten dependències d’enllaços externs en visualitzar el recurs.</p>'''+credits+'''</section></main><footer>Un recurs per observar, comprendre i comparar.</footer></body></html>'''
(p/'index.html').write_text(page)
